mapper.sql:
WHERE c.deleted = FALSE
AND (c.case_name ILIKE #{q.keywordLike} ESCAPE '\' OR c.content ILIKE #{q.keywordLike} ESCAPE '\')
AND c.domain_codes @> to_jsonb(#{q.domainCode}::TEXT)
AND c.quality_marks @> to_jsonb(#{q.qualityMark}::TEXT)
AND c.case_state = #{q.caseState}
AND c.contributing_org ILIKE #{q.contributingOrgLike} ESCAPE '\'
AND c.owner_no = #{q.ownerNo}
AND c.published_at >= #{q.publishedFrom}
AND c.published_at < (#{q.publishedTo}::DATE + 1)
AND (EXISTS (SELECT 1 FROM dtl_case_view v WHERE v.case_id = c.id AND v.viewed_at >= NOW() - INTERVAL '30 days') OR EXISTS (SELECT 1 FROM dtl_case_like l WHERE l.case_id = c.id AND l.liked_at >= NOW() - INTERVAL '30 days') OR EXISTS (SELECT 1 FROM dtl_case_comment m WHERE m.case_id = c.id AND m.deleted = FALSE AND m.commented_at >= NOW() - INTERVAL '30 days'))

mapper.select:
SELECT c.*, owner.employee_name AS owner_name, reviewer.employee_name AS reviewer_name,
FROM biz_case c LEFT JOIN org_employee owner ON owner.employee_no = c.owner_no AND owner.deleted = FALSE LEFT JOIN org_employee reviewer ON reviewer.employee_no = c.reviewer_no AND reviewer.deleted = FALSE
ORDER BY ${sortExpression}, c.id DESC LIMIT #{q.pageSize} OFFSET #{offset}
